    """ใบที่จ่ายแล้ว / หักจากเงินลูกค้า (ก่อนจ่ายเป็นงวด) -> งวดเดียวเต็มยอด + ย้ายรายการสมุดบัญชีเดิมมาผูกกับงวด"""
    RebatePayout = apps.get_model('stocks', 'RebatePayout')
    Payment = apps.get_model('stocks', 'RebatePayoutPayment')
    BankTransaction = apps.get_model('stocks', 'BankTransaction')
    for payout in RebatePayout.objects.filter(status__in=('PAID', 'DEDUCTED')):
        if payout.status == 'DEDUCTED':
            inst = Payment.objects.create(payout=payout, method='DEDUCT', amount=payout.rebate_amount or 0,
                                          deduct_month=payout.deduct_month)
        else:
            inst = Payment.objects.create(payout=payout, method='SEPARATE', amount=payout.rebate_amount or 0,
                                          paid_date=payout.paid_date or payout.payout_date,
                                          bank_account_id=payout.bank_account_id,
                                          exchange_rate=payout.exchange_rate)
        BankTransaction.objects.filter(rebate_payout=payout).update(rebate_payout=None, rebate_installment=inst)
        RebatePayout.objects.filter(pk=payout.pk).update(status='PAID')


